(()=>{var n="20261024-open-v1";document.documentElement.removeAttribute("data-entrance");document.querySelector("#entrance")?.remove();var e=document.createElement("script");e.src="game.bundle.js?v="+n;e.onerror=()=>{let t=document.querySelector("#app");t&&(t.innerHTML='<section class="question-loading"><h1>THE GAME COULD NOT LOAD.</h1><p>Check your connection, then try again.</p><button class="pixel-button" id="retry-game-load">TRY AGAIN</button></section>',document.querySelector("#retry-game-load").onclick=()=>location.reload())};document.head.append(e);})();
